import { Component, computed, inject, input } from '@angular/core';
import { Session } from '../../core/session';
import { Claim, money } from '../claims/claims-api';
import { GRADES } from '../people/people-api';
import { Period, periodDueCents } from '../periods/periods-api';

/** The statuses the summary counts, in the order it lists them. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

/** How many of the claims have each status, in the order the summary lists them. */
export function statusCounts(claims: Claim[]): { status: string; count: number }[] {
  return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === (status as string)).length }));
}

/** A person as the summary counts them: their grade in force on the sheet's today, whether they
 *  are retired, their due-total in cents (null: n/a), and whether they are active. */
export interface SummaryPerson {
  grade: string;
  retired: boolean;
  due: number | null;
  active: boolean;
}

// The sheet in figures, each as the lists show it: per grade, how many people not retired are on it
// today, their due-totals added up (n/a skipped) and how many of them are active; per period, its due-total and its change from the period before it by start date; per status, how
// many claims have it; per void reason on the sheet's list, how many VOID claims were voided with it.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <table data-testid="summary-grades">
        <caption>By grade</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due</th><th scope="col">Active</th></tr>
        </thead>
        <tbody>
          @for (g of byGrade(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
}

/** Whether a claim is a correction: its amount is negative. */
export function isCorrection(c: Claim): boolean {
  return c.amount.startsWith('-');
}

/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN one). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim's due is bound to statedDue: stated and not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: OPEN, deferred until a date after it. Until
 *  then it counts in no total, is not overdue and cannot be settled. */
export function deferred(c: Claim, today: string | null): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** Whether a claim counts toward claimed and due totals on the sheet's today: only open (OPEN or
 *  PENDING) and SETTLED ones do, but not a deferred one. */
export function counts(c: Claim, today: string | null): boolean {
  return (isOpen(c) || c.status === 'SETTLED') && !deferred(c, today);
}

/** A claim's due-by (yyyy-mm-dd), fixed when it was created. */
export function dueBy(c: Claim): string {
  return c.dueBy;
}

/** The date a claim is overdue after: its due-by plus the grace days of its person's grade in
 *  force on its date (0: none). */
export function lateFrom(c: Claim, grace = 0): string {
  return grace === 0 ? dueBy(c) : plusDays(dueBy(c), grace);
}

/** Whether a claim is overdue: open (OPEN or PENDING), not deferred, with its due-by plus its
 *  grace days before the sheet's today. */
export function overdue(c: Claim, today: string | null, grace = 0): boolean {
  return isOpen(c) && today !== null && lateFrom(c, grace) < today && !deferred(c, today);
}

