      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: voidError(e, this.isOpenerOrEditor(c)) }));
    }
  }

  /** Open, settle, approve, re-settle, void, delete or restore a claim; a move its status does not allow shows an error on the claim. */
  protected async changeStatus(c: Claim, action: ClaimAction): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const claim = await this.api.changeStatus(sheetId, c.id, action);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      const err = action === 'resettle' ? resettleError(e) : action === 'delete' ? deleteError(e)
        : action === 'restore' ? restoreError(e) : statusError(e, this.isOpenerOrEditor(c));
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: err }));
    }
  }

  /** Whether the user opened or last edited the claim, and so may not settle or approve it. */
  private isOpenerOrEditor(c: Claim): boolean {
    const user = this.session.user();
    return c.openedBy === user || c.editedBy === user;
  }

  protected splitAmountChanged(id: number, amount: string): void {
    this.clearRowError(id);
    this.splitAmounts.update((as) => ({ ...as, [id]: amount }));
  }

  /** Split the amount typed for it off an OPEN claim; the original keeps the rest and the new
   *  claim is listed first. A refusal shows an error on the claim. */
  protected async split(c: Claim): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const amount = (this.splitAmounts()[c.id] ?? '').trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Enter an amount with up to two decimals to split off.' }));
      return;
    }
    try {
      const { original, split } = await this.api.split(sheetId, c.id, amount);
      this.splitAmounts.update(({ [c.id]: _, ...rest }) => rest);
      if (this.session.sheetId() === sheetId) {
        this.saved.emit(original);
        this.saved.emit(split);
      }
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: splitError(e) }));
    }
  }

  protected inlineAmountChanged(id: number, amount: string): void {
    this.clearRowError(id);
    this.inlineAmounts.update((as) => ({ ...as, [id]: amount }));

export function restoreError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 409) return "Only a deleted claim can be restored, and only on the sheet's today it was deleted.";
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That claim is no longer on this sheet.';
  if (e instanceof HttpErrorResponse && e.status === 423) return 'This claim is due in a closed period.';
  return otherError(e);
}

export function statusError(e: unknown, opener: boolean): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a reason for rejecting the claim.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'This claim cannot make that change from its status, is deferred, was settled more than 7 days ago, or its person already has the most open claims its period allows.';
  if (e instanceof HttpErrorResponse && e.status === 403) {
    return opener
      ? 'The user who opened or last edited this claim cannot settle or approve it, or your role may not make that change.'
      : 'Your role may not make that change to this claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That claim is no longer on this sheet.';
  if (e instanceof HttpErrorResponse && e.status === 423) return 'This claim is due in a closed period.';
  if (e instanceof HttpErrorResponse && e.status === 422) {
    return 'This claim\'s due is above a threshold: it needs a note to be opened, or a proof to be settled or approved.';
  }
  return otherError(e);
}

